// Extraire les données du job
const input = $input.first().json;
const body = input.body || input;

// Stocker les données pour le traitement async
return [{
  json: {
    jobId: body.job_id,
    traite: body.traite,
    page: body.page,
    mode: body.mode || 'premium',
    targetLanguage: body.target_language || 'fr',
    apiKey: body.api_key,
    openaiApiKey: body.openai_api_key,
    sourceTextId: body.source_text_id,
    reference: body.reference,
    segments: body.segments || [],
    requestId: body.request_id
  }
}];

// Mettre le statut à in_progress
const input = $input.first().json;
const fs = require('fs');

const jobPath = `/tmp/torah-jobs/${input.jobId}.json`;

try {
  const content = fs.readFileSync(jobPath, 'utf8');
  const jobData = JSON.parse(content);
  jobData.status = 'in_progress';
  jobData.updated_at = new Date().toISOString();
  fs.writeFileSync(jobPath, JSON.stringify(jobData, null, 2));
} catch (e) {
  // Ignorer les erreurs de fichier
}

return [{ json: input }];

// Convertir les segments en items pour la boucle
const input = $input.first().json;

const items = input.segments.map((segment, index) => ({
  json: {
    segmentIndex: index,
    segmentText: segment,
    totalSegments: input.segments.length,
    jobId: input.jobId,
    traite: input.traite,
    page: input.page,
    mode: input.mode,
    targetLanguage: input.targetLanguage,
    apiKey: input.apiKey,
    openaiApiKey: input.openaiApiKey,
    sourceTextId: input.sourceTextId,
    reference: input.reference,
    requestId: input.requestId
  }
}));

return items;

